-- Fixture estrutural extraída de catálogos em 22/10/2026. Sem registros de produção.
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY,is_anonymous boolean DEFAULT false,deleted_at timestamptz,banned_until timestamptz);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claims',true)::jsonb->>'sub','')::uuid $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb $$;
GRANT USAGE ON SCHEMA public, auth TO anon,authenticated,service_role;
CREATE SEQUENCE public.apontamentos_op_id_seq;
CREATE SEQUENCE public.log_importacao_op_id_seq;
CREATE TABLE public.apontamentos_op (
