  data_referencia date NOT NULL,
  criado_em timestamp with time zone DEFAULT now() NOT NULL,
  log_importacao_op_id bigint,
  origem integer NOT NULL,
  op integer NOT NULL,
  cod_produto text NOT NULL,
  descricao text NOT NULL,
  cod_estagio integer NOT NULL,
  estagio text NOT NULL,
  unidade text NOT NULL,
  qtd_prevista numeric,
  qtd_produzida numeric,
  qtd_apontamentos integer,
  tempo_real numeric,
  tempo_previsto numeric,
  tempo_parada numeric,
  kg_hora_real numeric,
  kg_hora_previsto numeric,
  perc_tempo numeric
);
CREATE TABLE public.categorias_agrupamento (
