  data_referencia date
);
CREATE TABLE public.log_importacao_cadastro_mestre (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  arquivo_nome text NOT NULL,
  tipo_arquivo text NOT NULL,
  arquivo_hash text,
  identificador_lote text,
  fonte_sistema text DEFAULT 'ERP'::text NOT NULL,
  iniciado_em timestamp with time zone DEFAULT now() NOT NULL,
  finalizado_em timestamp with time zone,
  status text DEFAULT 'processando'::text NOT NULL,
  total_registros integer DEFAULT 0 NOT NULL,
  registros_processados integer DEFAULT 0 NOT NULL,
  registros_inseridos integer DEFAULT 0 NOT NULL,
  registros_atualizados integer DEFAULT 0 NOT NULL,
  registros_erro integer DEFAULT 0 NOT NULL,
