CREATE TABLE public.log_importacao_op (
  id bigint DEFAULT nextval('log_importacao_op_id_seq'::regclass) NOT NULL,
  data_referencia date NOT NULL,
  criado_em timestamp with time zone DEFAULT now() NOT NULL,
  total_linhas integer,
  arquivo_nome text,
  status text,
  linhas_importadas integer,
  linhas_erro integer,
  finalizado_em timestamp with time zone
);
CREATE TABLE public.mapa_produtos (
  codigo_produto text NOT NULL,
  origem_id text,
  familia_id text,
  agrupamento_cod text
);
