CREATE OR REPLACE FUNCTION public.fn_upsert_mapa_produtos_por_codigo(p_codigo_produto bigint)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  insert into mapa_produtos (codigo_produto, origem_id, familia_id, agrupamento_cod)
  select
    d.codigo_produto,
    d.origem_id,
    d.familia_id,
    d.agrupamento_cod
  from dicionario_produtos d
  where d.codigo_produto = p_codigo_produto
    and d.familia_id is not null  -- regra crítica
  on conflict (codigo_produto)
  do update set
    origem_id = excluded.origem_id,
    familia_id = excluded.familia_id,
    agrupamento_cod = excluded.agrupamento_cod;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.fn_upsert_mapa_produtos_por_codigo(p_codigo_produto text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  insert into mapa_produtos (codigo_produto, origem_id, familia_id, agrupamento_cod)
  select
    d.codigo_produto::text,
    d.origem_id,
    d.familia_id,
    d.agrupamento_cod
  from dicionario_produtos d
  where d.codigo_produto::text = p_codigo_produto
    and d.familia_id is not null
  on conflict (codigo_produto)
  do update set
    origem_id = excluded.origem_id,
    familia_id = excluded.familia_id,
    agrupamento_cod = excluded.agrupamento_cod;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.inserir_custo(p_codigo_produto text, p_descricao text, p_custo_total numeric, p_data_referencia date)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  v_origem_id uuid;
  v_familia_id uuid;
  v_agrupamento text;
begin

  -- garantir produto existe
  if not exists (
    select 1 from dicionario_produtos 
    where codigo_produto = p_codigo_produto
  ) then
    insert into dicionario_produtos (
      codigo_produto,
      descricao
    )
    values (
      p_codigo_produto,
      p_descricao
    );
  end if;

  -- buscar no mapa
  select origem_id, familia_id, agrupamento_cod
  into v_origem_id, v_familia_id, v_agrupamento
  from mapa_produtos
  where codigo_produto = p_codigo_produto;

  -- 🔥 AQUI ESTÁ O QUE ESTÁ FALTANDO NO TEU SISTEMA
  update dicionario_produtos
  set 
    origem_id = v_origem_id,
    familia_id = v_familia_id,
    agrupamento_cod = v_agrupamento,
    atualizado_em = now()
  where codigo_produto = p_codigo_produto;

  -- inserir custo
  insert into historico_custos (
    codigo_produto,
    descricao_na_planilha,
    custo_total,
    data_referencia
  )
  values (
    p_codigo_produto,
    p_descricao,
    p_custo_total,
    p_data_referencia
  )
  on conflict (codigo_produto, data_referencia)
  do update set
    custo_total = excluded.custo_total,
    descricao_na_planilha = excluded.descricao_na_planilha;

end;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_categoriza_apos_import()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  perform public.fn_upsert_mapa_produtos_por_codigo(new.codigo_produto::text);
  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.trg_categoriza_apos_import_produto()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  perform public.fn_upsert_mapa_produtos_por_codigo((new."Produto")::bigint);
  return new;
end;
$function$
;
CREATE TRIGGER tg_categoriza_apos_import AFTER INSERT OR UPDATE OF codigo_produto ON public.historico_custos FOR EACH ROW EXECUTE FUNCTION trg_categoriza_apos_import();
CREATE VIEW public.vw_produtos_orfaos_agrupamento AS  SELECT dp.codigo_produto,
    dp.descricao,
    dp.agrupamento_cod,
        CASE
            WHEN dp.agrupamento_cod = 'SEM_AGRUPAMENTO'::text THEN 'PENDENTE_CATEGORIZACAO'::text
            WHEN ca.id IS NULL THEN 'AGRUPAMENTO_INVALIDO'::text
            ELSE 'OK'::text
        END AS status_agrupamento
   FROM dicionario_produtos dp
     LEFT JOIN categorias_agrupamento ca ON ca.id = dp.agrupamento_cod;
